function MillHopperSightGlassMaker.init() MillHopperSightGlassMaker.ironStock=14; MillHopperSightGlassMaker.bronzeStock=12; MillHopperSightGlassMaker.woodStock=12; MillHopperSightGlassMaker.leatherStock=8; MillHopperSightGlassMaker.silverStock=8; MillHopperSightGlassMaker.goldStock=6; MillHopperSightGlassMaker.jewelStock=4; MillHopperSightGlassMaker.pearlStock=4; MillHopperSightGlassMaker.productStock={}; MillHopperSightGlassMaker.buildings={}; MillHopperSightGlassMaker.maker=nil; MillHopperSightGlassMaker.activeMaking={}; MillHopperSightGlassMaker.totalProducts=0; MillHopperSightGlassMaker.dayTimer=0; print("[MillHopperSightGlassMaker] Royal Mill Hopper Sight Glass Maker System initialized (6 products, 4 buildings)") end
function MillHopperSightGlassMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MillHopperSightGlassMaker.maker={name=n or ("Okničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Okničar najet: %s (spretnost: %d)",MillHopperSightGlassMaker.maker.name,s),"success") end; return true end
function MillHopperSightGlassMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MillHopperSightGlassMaker.build(id) local ok,e=MillHopperSightGlassMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MillHopperSightGlassMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MillHopperSightGlassMaker.getQualityBonus() local b=0; for _,bd in ipairs(MillHopperSightGlassMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MillHopperSightGlassMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillHopperSightGlassMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillHopperSightGlassMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillHopperSightGlassMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillHopperSightGlassMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillHopperSightGlassMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillHopperSightGlassMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillHopperSightGlassMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillHopperSightGlassMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillHopperSightGlassMaker.buildings==0 then return false,"Potrebna oknična delavnica" end; if not MillHopperSightGlassMaker.maker then return false,"Potreben oknicar" end; return true end
function MillHopperSightGlassMaker.make(pt,qty) qty=qty or 1; local ok,e=MillHopperSightGlassMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MillHopperSightGlassMaker.ironStock=MillHopperSightGlassMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MillHopperSightGlassMaker.bronzeStock=MillHopperSightGlassMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MillHopperSightGlassMaker.woodStock=MillHopperSightGlassMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MillHopperSightGlassMaker.leatherStock=MillHopperSightGlassMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MillHopperSightGlassMaker.silverStock=MillHopperSightGlassMaker.silverStock-d.silverCost*qty end; if d.goldCost then MillHopperSightGlassMaker.goldStock=MillHopperSightGlassMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MillHopperSightGlassMaker.jewelStock=MillHopperSightGlassMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MillHopperSightGlassMaker.pearlStock=MillHopperSightGlassMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MillHopperSightGlassMaker.maker then t=math.max(1,t-math.floor(MillHopperSightGlassMaker.maker.skill/13)) end; table.insert(MillHopperSightGlassMaker.activeMaking,{id="millhoppersightglass_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MillHopperSightGlassMaker.completeMaking(m) local q=1.0+(MillHopperSightGlassMaker.getQualityBonus()/100); if MillHopperSightGlassMaker.maker then q=q+(MillHopperSightGlassMaker.maker.skill/140) end; q=math.min(2.5,q); MillHopperSightGlassMaker.productStock[m.productType]=(MillHopperSightGlassMaker.productStock[m.productType] or 0)+m.quantity; MillHopperSightGlassMaker.totalProducts=MillHopperSightGlassMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillHopperSightGlassMaker.maker then MillHopperSightGlassMaker.maker.itemsMade=MillHopperSightGlassMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillHopperSightGlassMaker.maker.skill=math.min(100,MillHopperSightGlassMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Okence izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millhoppersightglass.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MillHopperSightGlassMaker.update(dt) if not _G.state then return end; MillHopperSightGlassMaker.dayTimer=MillHopperSightGlassMaker.dayTimer+dt; if MillHopperSightGlassMaker.dayTimer>=30 then MillHopperSightGlassMaker.dayTimer=0; for i=#MillHopperSightGlassMaker.activeMaking,1,-1 do local m=MillHopperSightGlassMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MillHopperSightGlassMaker.completeMaking(m); table.remove(MillHopperSightGlassMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MillHopperSightGlassMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MillHopperSightGlassMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
